/*
 * TRAXXAS TRX-4 HIL DIGITAL TWIN — WI-FI PI HOST -> ARDUINO NANO PWM BRIDGE
 * Target: Arduino Nano V3.0 (ATmega328P, 5.0V TTL, 115200 baud)
 *
 * Upgraded Control Flow (Physical Touch Button Removed -> Wi-Fi Web UI):
 *   Computer Browser (Wi-Fi) <--> Raspberry Pi 5 (trx4_web_server.py :5000)
 *                                    | USB CDC / BenchTwin Serial (115200 baud)
 *                                    v
 *                              Arduino Nano D9..D12 (50Hz PWM) + D4 Active-LOW Buzzer
 *
 * Supported Serial Commands:
 *   $ESC,SHIFT,DIFF_F,DIFF_R        -> Drive 4 Traxxas PWM outputs (1000-2000 us)
 *   $ESC,SHIFT,DIFF_F,DIFF_R,ALARM  -> Drive 4 PWM outputs + Alarm (0=OFF, 1=ON)
 *   ALARM:1 / ALARM:0               -> Sound / silence Active-LOW Buzzer (D4)
 *   FREE / HARSH / STOP             -> Bench preset test modes
 *   HOLD / LIVE / PING              -> Pause watchdog / Resume 300ms watchdog / PONG
 */

#include <Servo.h>

const int PIN_BUZZER     = 4;
const int PIN_ESC        = 9;
const int PIN_SHIFT      = 10;
const int PIN_DIFF_FRONT = 11;
const int PIN_DIFF_REAR  = 12;
const int PIN_STATUS_LED = 13;

const int PWM_MIN_US     = 1000;
const int PWM_MAX_US     = 2000;
const int ESC_NEUTRAL_US = 1500;
const int SERVO_SAFE_US  = 1900;

const unsigned long FAILSAFE_TIMEOUT_MS = 300;

Servo escThrottle;
Servo servoShift;
Servo servoDiffFront;
Servo servoDiffRear;

bool watchdogEnabled = true;
bool failsafeActive  = true;
bool stopAlarmActive = false;

unsigned long lastValidPacketMs = 0;
unsigned long lastLedToggleMs   = 0;

void writeOutputs(int esc, int shift, int diffF, int diffR) {
  escThrottle.writeMicroseconds(esc);
  servoShift.writeMicroseconds(shift);
  servoDiffFront.writeMicroseconds(diffF);
  servoDiffRear.writeMicroseconds(diffR);
}

void setBuzzerAlarm(bool active) {
  stopAlarmActive = active;
  // Open-drain Active-LOW drive: sinks LOW when active, releases HIGH-Z when off
  // so 5.0V Nano output never contends with 3.3V Raspberry Pi GPIO 17.
  if (active) {
    pinMode(PIN_BUZZER, OUTPUT);
    digitalWrite(PIN_BUZZER, LOW);
  } else {
    pinMode(PIN_BUZZER, INPUT);
  }
}

void applyFailsafe() {
  writeOutputs(ESC_NEUTRAL_US, SERVO_SAFE_US, SERVO_SAFE_US, SERVO_SAFE_US);
  setBuzzerAlarm(false);
  failsafeActive = true;
}

bool parseStrictPwm(String s, int &outVal) {
  int len = s.length();
  if (len != 4) return false;
  int val = 0;
  for (int i = 0; i < len; i++) {
    int ch = s.charAt(i);
    if (ch < '0' || ch > '9') return false;
    val = val * 10 + (ch - '0');
  }
  if (val < PWM_MIN_US || val > PWM_MAX_US) return false;
  outVal = val;
  return true;
}

void processLine(String raw) {
  int endIdx = raw.length();
  while (endIdx > 0 && (raw.charAt(endIdx - 1) == '\r' || raw.charAt(endIdx - 1) == ' ')) {
    endIdx--;
  }
  if (endIdx == 0) return;
  String line = raw.substring(0, endIdx);

  if (line.equalsIgnoreCase("PING")) {
    Serial.println("PONG");
    return;
  }
  if (line.equalsIgnoreCase("HOLD")) {
    watchdogEnabled = false;
    Serial.println("MODE:HOLD (Wi-Fi Web Dashboard Ready)");
    return;
  }
  if (line.equalsIgnoreCase("LIVE")) {
    watchdogEnabled = true;
    setBuzzerAlarm(false);
    lastValidPacketMs = millis();
    Serial.println("MODE:LIVE (300ms USB Watchdog active)");
    return;
  }
  if (line.equalsIgnoreCase("ALARM:1")) {
    setBuzzerAlarm(true);
    Serial.println("ALARM:ON (Active-LOW Buzzer)");
    return;
  }
  if (line.equalsIgnoreCase("ALARM:0")) {
    setBuzzerAlarm(false);
    Serial.println("ALARM:OFF");
    return;
  }
  if (line.equalsIgnoreCase("FREE")) {
    watchdogEnabled = false;
    failsafeActive = false;
    setBuzzerAlarm(false);
    writeOutputs(2000, 1100, 1100, 1100);
    Serial.println("WIFI:FREE -> OK:2000,1100,1100,1100");
    return;
  }
  if (line.equalsIgnoreCase("HARSH")) {
    watchdogEnabled = false;
    failsafeActive = false;
    setBuzzerAlarm(false);
    writeOutputs(1625, 1900, 1900, 1900);
    Serial.println("WIFI:HARSH -> OK:1625,1900,1900,1900");
    return;
  }
  if (line.equalsIgnoreCase("STOP")) {
    watchdogEnabled = false;
    failsafeActive = false;
    writeOutputs(1500, 1900, 1900, 1900);
    setBuzzerAlarm(true);
    Serial.println("WIFI:STOP -> OK:1500,1900,1900,1900 + ALARM");
    return;
  }

  if (!line.startsWith("$")) {
    Serial.println("ERR:BAD_PREFIX");
    return;
  }

  int c1 = line.indexOf(',', 1);
  int c2 = (c1 > 0) ? line.indexOf(',', c1 + 1) : -1;
  int c3 = (c2 > 0) ? line.indexOf(',', c2 + 1) : -1;
  int c4 = (c3 > 0) ? line.indexOf(',', c3 + 1) : -1;
  if (c1 < 0 || c2 < 0 || c3 < 0 || (c4 > 0 && line.indexOf(',', c4 + 1) >= 0)) {
    Serial.println("ERR:BAD_FIELDS");
    return;
  }

  int esc = 0, shift = 0, diffF = 0, diffR = 0;
  String diffRStr = (c4 > 0) ? line.substring(c3 + 1, c4) : line.substring(c3 + 1);
  if (!parseStrictPwm(line.substring(1, c1), esc) ||
      !parseStrictPwm(line.substring(c1 + 1, c2), shift) ||
      !parseStrictPwm(line.substring(c2 + 1, c3), diffF) ||
      !parseStrictPwm(diffRStr, diffR)) {
    Serial.println("ERR:RANGE");
    return;
  }

  if (c4 > 0) {
    int alm = line.substring(c4 + 1).toInt();
    setBuzzerAlarm(alm != 0);
  }

  writeOutputs(esc, shift, diffF, diffR);
  lastValidPacketMs = millis();
  failsafeActive = false;

  Serial.print("OK:");
  Serial.print(esc);   Serial.print(",");
  Serial.print(shift); Serial.print(",");
  Serial.print(diffF); Serial.print(",");
  Serial.println(diffR);
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_STATUS_LED, OUTPUT);
  setBuzzerAlarm(false);

  escThrottle.attach(PIN_ESC);
  servoShift.attach(PIN_SHIFT);
  servoDiffFront.attach(PIN_DIFF_FRONT);
  servoDiffRear.attach(PIN_DIFF_REAR);

  applyFailsafe();
  lastValidPacketMs = millis();

  Serial.println("TRX4_PWM_BRIDGE_READY");
  Serial.println("Wi-Fi Dashboard Mode: Use http://<pi-ip>:5000 (or send HOLD / $2000,1100,1100,1100 / STOP)");
}

void loop() {
  if (Serial.available() > 0) {
    String line = Serial.readStringUntil('\n');
    processLine(line);
  }

  unsigned long now = millis();
  if (watchdogEnabled && !failsafeActive && (now - lastValidPacketMs > FAILSAFE_TIMEOUT_MS)) {
    applyFailsafe();
    Serial.println("FAILSAFE:TIMEOUT");
  }

  if (now - lastLedToggleMs >= (failsafeActive ? 150 : 500)) {
    lastLedToggleMs = now;
    digitalWrite(PIN_STATUS_LED, !digitalRead(PIN_STATUS_LED));
  }
  delay(10);
}
